const modules = [...settings.matchAll(/":([^"\n]+)"/g)].map((match) => match[1].split(":").at(-1));
const invalidModules = modules.filter((module) => !module.startsWith(convention.artifactPrefix));
if (invalidModules.length > 0) throw new Error(`public modules violate artifact prefix: ${invalidModules.join(", ")}`);
const invalidPackages = [];
for (const file of await javaFiles(path.join(root, "ji-java"))) {
  const source = await readFile(file, "utf8");
  const declaration = source.match(/^package\s+([^;]+);/m)?.[1];
  if (declaration && !declaration.startsWith(convention.javaPackagePrefix)) {
    invalidPackages.push(`${path.relative(root, file)} declares ${declaration}`);
  }
}
if (invalidPackages.length > 0) throw new Error(`Java packages violate naming contract:\n${invalidPackages.join("\n")}`);
if (!environment.includes(convention.environmentPrefix)) throw new Error("environment variable prefix is undocumented");
process.stdout.write("public naming conventions verified\n");

async function javaFiles(directory) {
  const result = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    if (entry.name === "build") continue;
    const child = path.join(directory, entry.name);
    if (entry.isDirectory()) result.push(...await javaFiles(child));
    else if (entry.isFile() && entry.name.endsWith(".java")) result.push(child);
  }
  return result;
}
